+const { useState, useRef, useId } = React;
+
+function RadioOption({ name, value, label, checked, onChange, required, inputRef }) {
+  const id = useId();
+  return (
+    <label className="radio-option" htmlFor={id}>
+      <input
+        ref={inputRef}
+        id={id}
+        type="radio"
+        name={name}
+        value={value}
+        checked={checked}
+        onChange={onChange}
+        required={required}
+      />
+      <span className="radio-label">{label}</span>
+    </label>
+  );
+}
+
+function NotificationForm() {
+  const options = [
+    { value: "email", label: "Email" },
+    { value: "sms", label: "SMS" },
+    { value: "push", label: "Push Notifications" },
+  ];
+
+  const [selected, setSelected] = useState("");
+  const [status, setStatus] = useState({ kind: "", message: "" });
+  const firstRadioRef = useRef(null);
+
+  const handleSubmit = (e) => {
+    e.preventDefault();
+    if (!selected) {
+      setStatus({
+        kind: "error",
+        message: "Error: Please choose how you'd like to receive notifications.",
+      });
+      if (firstRadioRef.current) firstRadioRef.current.focus();
+      return;
+    }
+    const labelText = options.find((o) => o.value === selected).label;
+    setStatus({
+      kind: "success",
+      message: `Preference saved. You'll receive notifications via ${labelText}.`,
+    });
+  };
+
+  return (
+    <form className="card" noValidate onSubmit={handleSubmit}>
+      <p className="required-legend">
